args.command:
cd /workspace && echo "=== imports found ===" && grep -nE '^\s*(import|from)\s+' wc_plus.py test_wc_plus.py && echo "=== stdlib-only check (isolated sys.path, no site-packages) ===" && python3 -S -c "
import sys, importlib, pathlib
mods=set()
import ast
for f in ['wc_plus.py','test_wc_plus.py']:
    t=ast.parse(pathlib.Path(f).read_text())
    for n in ast.walk(t):
        if isinstance(n,ast.Import):
            for a in n.names: mods.add(a.name.split('.')[0])
        elif isinstance(n,ast.ImportFrom):
            if n.level==0 and n.module: mods.add(n.module.split('.')[0])
print('top-level imports:',sorted(mods))
local={'wc_plus'}
std=set(sys.stdlib_module_names)
third=[m for m in mods if m not in std and m not in local]
print('non-stdlib, non-local:',third)
print('RESULT:', 'STDLIB-ONLY OK' if not third else 'THIRD-PARTY FOUND')
"

